head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBndTpCd = '';
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 파라미터추출
        const prt = $c.frame.path("../");
        if (prt !== undefined) {
            scwin.fn_GetPar = prt.scwin.fn_GetPar;
            scwin.fn_SetPar = prt.scwin.fn_SetPar;
        }
        if (scwin.fn_GetPar !== undefined) {
            let arrPar = new Array();
            scwin.fn_GetPar(arrPar);
            if (typeof(arrPar[0].BND_TP_CD) !== 'undefined') {
                scwin.vBndTpCd = arrPar[0].BND_TP_CD;
            }
            url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
            url += "&outputMessageId=BNS_BND_CLSS";
            url += "&queryId=lds.stf.bnscommon.select.listBndClssCd";
            url += "&SCREN_ID=" + "ULDBNS90003.xml";
            url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
            const sbmOptions = {
                id : "sbm_dts_List",
                action : "/listingCommon.do",
                ref : "",
                target : "dts_List=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90002.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90002.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount > 0) {
            scwin.setRowFocus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90002.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        if (row > 0) {
            const bndClssCd = dts_List.getCellData(dts_List.getRowPosition(), "BND_CLSS_CD");
            if (bndClssCd !== '000000') {
                let showAlert = false;
                const tempStr = bndClssCd.substring(0, 3);
                // 국채
                if (scwin.vBndTpCd === 'GB' && tempStr !== '111') showAlert = true;
                // 지방채

                else if (scwin.vBndTpCd === 'MB' && tempStr !== '112') showAlert = true;
                // 특수채

                else if (scwin.vBndTpCd === 'AB' && tempStr !== '113') showAlert = true;
                // 회사채

                else if (scwin.vBndTpCd === 'CO' && tempStr !== '116') showAlert = true;
                // 외국채

                else if (scwin.vBndTpCd === 'FO' && tempStr !== '130') showAlert = true;
                if (showAlert) {
                    if (!window.confirm('채권분류코드가 채권유형과 일치하지 않습니다.\n계속 진행하시겠습니까?')) return;
                }
            }
            const bndTpNm = dts_List.getCellData(dts_List.getRowPosition(), "BND_TP_NM");
            let arrPar = new Array();
            arrPar[0] = {
                BND_CLSS_CD: bndClssCd,
                BND_TP_NM: bndTpNm,
                BND_TP_NM1: bndClssCd + " " + bndTpNm
            };
            scwin.fn_SetPar(arrPar);
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90002.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90002.img_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setRowFocus
 * @description 부모창에서 넘어온 채권유형에 따라 해당 위치를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setRowFocus = function() {
    if (scwin.vBndTpCd === '') return;
    let firstData = '';
    // 국채
    if (scwin.vBndTpCd === 'GB') {
        firstData = '111100'; // 국고채권

    }
    // 지방채
    else if (scwin.vBndTpCd === 'MB') {
        firstData = '112100'; // 서울도시철도공채증권

    }
    // 특수채
    else if (scwin.vBndTpCd === 'AB') {
        firstData = '113100'; // 통화안정증권

    }
    // 회사채
    else if (scwin.vBndTpCd === 'CO') {
        firstData = '116100'; // 일반사채

    }
    // 외국채
    else if (scwin.vBndTpCd === 'FO') {
        firstData = '130000'; // 외국채권

    }
    const tempPos = $c.cp.getNameValueRow(dts_List, "BND_CLSS_CD", firstData);
    dts_List.setRowPosition(dts_List.getRowCount(), 0);
    dts_List.setRowPosition(tempPos, 0);
};
